package dev.smokekitchen.test;

import dev.smokekitchen.content.*;
import dev.smokekitchen.cooking.CookingBatch;
import dev.smokekitchen.world.KitchenBlockEntity;
import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.fabricmc.fabric.api.client.gametest.v1.world.TestWorldSave;
import net.minecraft.core.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import java.util.function.Predicate;

/** Normal input packets, observed stages and elapsed game ticks; no injected cookedness. */
public final class FinishingFlowTest implements FabricClientGameTest {
    private static final BlockPos FISH=new BlockPos(0,100,0),RED=new BlockPos(2,100,0),RICE=new BlockPos(4,100,0),BOARD=new BlockPos(-1,100,0),SALAD=new BlockPos(0,100,2);
    private int cut=CookingBatch.Cut.DICE.ordinal();
    private static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
    private static KitchenBlockEntity pot(MinecraftServer game,BlockPos pos){return (KitchenBlockEntity)game.overworld().getBlockEntity(pos);}
    private static boolean named(KitchenBlockEntity p,String id){return ContentCatalog.DISHES.stream().filter(r->r.id().equals(id)).findFirst().orElseThrow().matches(p.batch)&&p.batch.ready()&&!p.batch.burnt();}
    private static double cooked(KitchenBlockEntity p){return p.batch.ingredients.stream().mapToDouble(x->x.cooked).min().orElse(0);}
    private static void equip(ClientGameTestContext c,TestServerContext s,String id){c.runOnClient(client->client.player.getInventory().setSelectedSlot(8));s.runCommand("item replace entity @a hotbar.8 with "+id);c.waitTicks(5);}
    private static void click(ClientGameTestContext c,BlockPos p,Direction face){c.runOnClient(client->client.gameMode.useItemOn(client.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(p),face,p,false)));c.waitTicks(6);}
    private static void select(ClientGameTestContext c,Item item){c.runOnClient(client->{for(int i=0;i<36;i++)if(i!=8&&client.player.getInventory().getItem(i).is(item)){if(i>8){client.gameMode.handleContainerInput(client.player.inventoryMenu.containerId,i,7,net.minecraft.world.inventory.ContainerInput.SWAP,client.player);client.player.getInventory().setSelectedSlot(7);}else client.player.getInventory().setSelectedSlot(i);return;}throw new AssertionError("Prepared item missing: "+item);});c.waitTicks(5);}
    private static boolean observe(TestServerContext s,Predicate<MinecraftServer> condition){boolean[] result={false};s.runOnServer(game->result[0]=condition.test(game));return result[0];}
    private static void until(ClientGameTestContext c,TestServerContext s,Predicate<MinecraftServer> condition,int ticks,String message){for(int n=0;n<ticks;n+=20){if(observe(s,condition))return;c.waitTicks(20);}check(observe(s,condition),message);}
    private void cut(ClientGameTestContext c,TestServerContext s,String id,CookingBatch.Cut wanted){equip(c,s,id);click(c,BOARD,Direction.UP);equip(c,s,"smoke_kitchen:stone_knife");c.getInput().holdKey(o->o.keyShift);c.waitTicks(3);while(cut!=wanted.ordinal()){click(c,BOARD,Direction.UP);cut=(cut+1)%CookingBatch.Cut.values().length;}c.getInput().releaseKey(o->o.keyShift);c.waitTicks(3);for(int i=0;i<4;i++)click(c,BOARD,Direction.UP);}
    private static void off(ClientGameTestContext c,TestServerContext s,BlockPos p){equip(c,s,"minecraft:air");for(int i=0;i<4&&!observe(s,g->pot(g,p).heat==0);i++)click(c,p,Direction.NORTH);check(observe(s,g->pot(g,p).heat==0),"Actual side controls must shut the burner off");}
    @Override public void runTest(ClientGameTestContext c) {
        TestWorldSave save;int[] gas=new int[3];double[] water=new double[2];
        try(var world=c.worldBuilder().create()) {
            save=world.getWorldSave();var s=world.getServer();s.runCommand("time set day");s.runCommand("weather clear");s.runCommand("fill -6 99 -6 7 99 6 minecraft:smooth_stone");s.runCommand("tp @a 1 100 -1 0 25");s.runCommand("gamemode survival @a");c.waitTicks(10);
            for(var p:new BlockPos[]{FISH,RED,RICE}){equip(c,s,"smoke_kitchen:gas_stove");click(c,p.below(),Direction.UP);}
            equip(c,s,"smoke_kitchen:frying_pan");click(c,FISH,Direction.UP);for(var p:new BlockPos[]{RED,RICE}){equip(c,s,"smoke_kitchen:soup_pot");click(c,p,Direction.UP);equip(c,s,"minecraft:air");click(c,p,Direction.UP);}
            equip(c,s,"smoke_kitchen:cutting_board");click(c,BOARD.below(),Direction.UP);equip(c,s,"smoke_kitchen:mixing_bowl");click(c,SALAD.below(),Direction.UP);
            for(int i=0;i<3;i++)cut(c,s,"minecraft:porkchop",CookingBatch.Cut.DICE);cut(c,s,"smoke_kitchen:ginger",CookingBatch.Cut.SLICE);for(int i=0;i<2;i++)cut(c,s,"smoke_kitchen:cucumber",CookingBatch.Cut.DICE);cut(c,s,"smoke_kitchen:garlic",CookingBatch.Cut.MINCE);
            for(int i=0;i<2;i++){select(c,KitchenContent.item("cucumber"));click(c,SALAD,Direction.UP);}select(c,KitchenContent.item("garlic"));click(c,SALAD,Direction.UP);for(String id:new String[]{"sesame_oil","salt","rice_vinegar"}){equip(c,s,"smoke_kitchen:"+id);click(c,SALAD,Direction.UP);}equip(c,s,"smoke_kitchen:ladle");for(int i=0;i<3;i++)click(c,SALAD,Direction.UP);s.runOnServer(g->check(named(pot(g,SALAD),"cucumber_salad"),"Actual cut vegetables, sesame oil and mixing must make cold salad"));equip(c,s,"minecraft:bowl");click(c,SALAD,Direction.UP);
            for(String id:new String[]{"rapeseed_oil","salt","pepper_powder","gas_canister"}){equip(c,s,"smoke_kitchen:"+id);click(c,FISH,id.equals("gas_canister")?Direction.NORTH:Direction.UP);}until(c,s,g->pot(g,FISH).batch.temperature>=130,600,"The oil pan must actually preheat");for(int i=0;i<2;i++){equip(c,s,"minecraft:cod");click(c,FISH,Direction.UP);}equip(c,s,"minecraft:air");until(c,s,g->cooked(pot(g,FISH))>=.4,1600,"Fish must set on its first side");equip(c,s,"smoke_kitchen:tongs");click(c,FISH,Direction.UP);s.runCommand("tp @a 0 100 -1 0 55");c.waitTicks(3);c.takeScreenshot("finishing-actual-turn-0.1.8");equip(c,s,"minecraft:air");until(c,s,g->named(pot(g,FISH),"pan_fried_fish"),1600,"The turned and peppered fish must actually finish");equip(c,s,"minecraft:bowl");click(c,FISH,Direction.UP);off(c,s,FISH);
            s.runCommand("tp @a 2 100 -1 0 55");equip(c,s,"smoke_kitchen:rapeseed_oil");click(c,RED,Direction.UP);equip(c,s,"minecraft:sugar");click(c,RED,Direction.UP);equip(c,s,"smoke_kitchen:gas_canister");click(c,RED,Direction.NORTH);until(c,s,g->pot(g,RED).batch.caramelSeconds>=3,600,"Actual dry hot oil and sugar must form colour");equip(c,s,"smoke_kitchen:thermometer");click(c,RED,Direction.UP);c.takeScreenshot("finishing-sugar-colour-0.1.8");for(int i=0;i<3;i++){select(c,Items.PORKCHOP);click(c,RED,Direction.UP);}select(c,KitchenContent.item("ginger"));click(c,RED,Direction.UP);equip(c,s,"smoke_kitchen:water_jug");click(c,RED,Direction.UP);click(c,RED,Direction.UP);equip(c,s,"smoke_kitchen:soy_sauce");click(c,RED,Direction.UP);equip(c,s,"smoke_kitchen:pot_lid");click(c,RED,Direction.UP);equip(c,s,"minecraft:air");for(int i=0;i<3;i++)click(c,RED,Direction.NORTH);s.runOnServer(g->check(pot(g,RED).heat==1,"Actual braising must switch to covered low heat"));
            equip(c,s,"minecraft:water_bucket");click(c,RICE,Direction.UP);equip(c,s,"smoke_kitchen:rice");click(c,RICE,Direction.UP);equip(c,s,"smoke_kitchen:ladle");click(c,RICE,Direction.UP);click(c,RICE,Direction.UP);equip(c,s,"smoke_kitchen:gas_canister");click(c,RICE,Direction.NORTH);equip(c,s,"minecraft:air");for(int i=0;i<3;i++)click(c,RICE,Direction.NORTH);
            until(c,s,g->cooked(pot(g,RICE))>=1,2600,"Rice must reach ordinary cookedness before softening");equip(c,s,"minecraft:bowl");click(c,RICE,Direction.UP);s.runOnServer(g->{var p=pot(g,RICE);check(p.batch.remainingServings==-1&&p.batch.progress(1.4)<100&&g.getPlayerList().getPlayers().getFirst().getMainHandItem().is(Items.BOWL),"Premature porridge serving must keep the bowl and its unserved softening batch");});equip(c,s,"smoke_kitchen:thermometer");click(c,RICE,Direction.UP);s.runCommand("tp @a 4 100 -1 0 55");c.waitTicks(5);c.takeScreenshot("finishing-porridge-still-softening-0.1.8");
            until(c,s,g->named(pot(g,RED),"braised_pork"),2400,"Actual sugar colour, diced meat, water and low simmer must produce braised pork");off(c,s,RED);equip(c,s,"minecraft:bowl");click(c,RED,Direction.UP);until(c,s,g->named(pot(g,RICE),"rice_porridge"),1400,"Porridge must actually reach its complete softening stage");off(c,s,RICE);equip(c,s,"minecraft:bowl");click(c,RICE,Direction.UP);s.runOnServer(g->{var porridge=g.getPlayerList().getPlayers().getFirst().getInventory().getNonEquipmentItems().stream().filter(x->x.is(KitchenContent.item("rice_porridge"))).findFirst().orElseThrow();var tag=porridge.get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag();check(tag.getIntOr("kitchen_quality",-1)==3&&!tag.getStringOr("kitchen_quality_reasons","").contains("bland"),"Actual plain porridge must not require salt or soy to have proper quality");});
            select(c,KitchenContent.item("pan_fried_fish"));s.runOnServer(g->g.getPlayerList().getPlayers().getFirst().getFoodData().setFoodLevel(8));c.runOnClient(client->client.player.setXRot(-70));c.getInput().holdKey(o->o.keyUse);c.waitTicks(40);c.getInput().releaseKey(o->o.keyUse);c.waitTicks(100);s.runOnServer(g->{check(g.getPlayerList().getPlayers().getFirst().getFoodData().getFoodLevel()>8,"The actual pan-fried fish must be edible");for(int i=0;i<3;i++)gas[i]=ResourceStates.gasUnits(pot(g,new BlockPos[]{FISH,RED,RICE}[i]).items.get(26));water[0]=pot(g,RED).batch.water;water[1]=pot(g,RICE).batch.water;});s.runCommand("tp @a 2 100 -3 0 25");c.waitTicks(5);c.takeScreenshot("finishing-served-real-dishes-0.1.8");
        }
        try(var world=save.open()) {
            c.waitTicks(10);world.getServer().runOnServer(g->{var positions=new BlockPos[]{FISH,RED,RICE,SALAD};var names=new String[]{"pan_fried_fish","braised_pork","rice_porridge","cucumber_salad"};for(int i=0;i<4;i++){var p=pot(g,positions[i]);check(p.batch.lockedDish.equals(names[i])&&p.batch.remainingServings==(i==1||i==2?2:1),"Actual reopening must retain "+names[i]);if(i<3)check(ResourceStates.gasUnits(p.items.get(26))==gas[i],"Saved fuel must remain exact");}check(Math.abs(pot(g,RED).batch.water-water[0])<.001&&Math.abs(pot(g,RICE).batch.water-water[1])<.001,"Saved soup water must remain exact");check(pot(g,FISH).batch.ingredients.stream().allMatch(p->p.turnedAfterSetting)&&pot(g,RED).batch.ingredients.stream().filter(p->p.id.equals("pork")).allMatch(p->p.caramelOnAdd),"Turn and caramel evidence must survive actual world reopening");});world.getServer().runCommand("tp @a 0 100 -1 0 55");c.getInput().holdKey(o->o.keyShift);c.waitTicks(30);c.takeScreenshot("finishing-shift-contents-after-reload-0.1.8");c.getInput().releaseKey(o->o.keyShift);c.waitTicks(3);
        }
    }
}
